css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .88); position: relative; }
.loader::before { content: ''; position: absolute; z-index: 3; top: 0; left: 0; width: 100%; height: 13%; border-radius: 3px; background: linear-gradient(color-mix(in srgb, #000 18%, var(--accent-2)), color-mix(in srgb, #000 38%, var(--accent-2))); }
.loader::after { content: ''; position: absolute; z-index: 3; bottom: 0; left: 0; width: 100%; height: 10%; border-radius: 3px; background: linear-gradient(color-mix(in srgb, #000 38%, var(--accent-2)), color-mix(in srgb, #000 18%, var(--accent-2))); }
.loader .platen { position: absolute; z-index: 2; left: 15%; width: 70%; height: 13%; border-radius: 2px; background: linear-gradient(var(--accent), color-mix(in srgb, #000 28%, var(--accent))); animation: press-down calc(var(--loader-speed) * 2.6) cubic-bezier(.5, 0, .3, 1) infinite; }
.loader .platen::after { content: ''; position: absolute; bottom: 100%; left: 44%; width: 12%; height: 340%; background: linear-gradient(90deg, #94a3b8, #e2e8f0, #94a3b8); }
.loader span { position: absolute; bottom: 10%; left: 34%; width: 32%; height: 26%; border-radius: 2px; transform-origin: bottom center; background: linear-gradient(var(--accent-2), color-mix(in srgb, #000 26%, var(--accent-2))); animation: crush calc(var(--loader-speed) * 2.6) cubic-bezier(.5, 0, .3, 1) infinite; }
@keyframes press-down { 0%, 12% { top: 13%; } 44%, 56% { top: 66%; } 88%, 100% { top: 13%; } }
@keyframes crush { 0%, 26% { transform: scale(1, 1); } 46%, 56% { transform: scale(1.28, .42); } 80%, 100% { transform: scale(1, 1); } }
